"""Generate the audit reading from its structured qualification. Run from the repository root."""
from pathlib import Path
from html import escape as e
import json
src=Path('sources/qualification-axelor-secteur-2026-10-31.json');d=json.loads(src.read_text(encoding='utf-8'));folder=Path('audits/2026-10-31-axelor-sectoriel')
def ul(values):return '<ul>'+''.join('<li>'+e(v)+'</li>' for v in values)+'</ul>'
summary=[('Saisons','Variantes et dates utilisables comme primitives.','Contextes indépendants et chevauchants, reconduction et affectation saisonnière du stock à compléter.'),('Allocations','Mouvements planifiés, stock projeté, demandes de réservation et réallocation selon dates.','Protection des achats attendus, arbitrage saison/canal et gestion des changements à qualifier.'),('Capacités','Créneaux de machines, calendriers et MRP.','Registre des engagements fournisseurs sans achat ferme à spécifier, puis raccorder à la faisabilité.')]
parts=['''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Axelor — saisons, allocations et capacités</title><style>
*{box-sizing:border-box}body{font:16px/1.65 'Segoe UI',Arial,sans-serif;color:#153b4a;background:#f7f6f2;margin:0}main{max-width:1120px;margin:auto;padding:32px 24px 70px}header{background:#d9f1e8;border-radius:16px;padding:30px;border-top:5px solid #23665d}h1{font-size:32px;line-height:1.25;margin:8px 0 15px}h2{font-size:24px;margin:38px 0 16px}h3{font-size:19px;margin:0 0 10px}h4{margin:16px 0 5px;font-size:15px}p{margin:8px 0 15px}a{color:#176359;text-underline-offset:3px}nav{display:flex;gap:22px;flex-wrap:wrap;margin:20px 0}.eyebrow{font-size:13px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.status{background:white;padding:18px;border-radius:8px;border-left:4px solid #ed8a38}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}.cards>article,.detail{padding:22px;background:white;border:1px solid #cfded9;border-radius:10px;min-width:0}.detail{margin:18px 0}.tag{font-size:12px;font-weight:700;color:#23665d}.detail li+li{margin-top:7px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;background:white}th,td{padding:13px 16px;border:1px solid #d2ded9;text-align:left;vertical-align:top}th{background:#e8f4ed}.note{padding:16px;background:#fff3e7;border-left:4px solid #ed8a38}code{font-size:13px;overflow-wrap:anywhere}.sources a{overflow-wrap:anywhere}.foot{font-size:13px;color:#50666f;margin-top:35px}@media(max-width:720px){main{padding:18px 14px}header{padding:20px}h1{font-size:26px}.cards{grid-template-columns:1fr}nav{gap:12px}.detail{padding:17px}}@media print{body{background:white}main{max-width:none}a{color:inherit}.detail{break-inside:avoid}}
</style><main><header><div class="eyebrow">Étude économique FLOW · Audit du 31 octobre 2026</div><h1>Axelor : quelles références pour les saisons, les allocations et les capacités ?</h1><p><strong>Les composants examinés sont des références partielles.</strong> Ils apportent des primitives réelles. Leur équivalence avec les exigences sectorielles Synvance n’est pas établie.</p><p>AOS v9.1.10 · code figé <code>'''+e(d['source_commit'])+'''</code></p></header><nav aria-label="Parcours de lecture"><a href="#synthese">Synthèse</a><a href="#complements">Compléments et financement</a><a href="#estimation">Conséquences sur l’estimation</a><a href="#preuves">Preuves et reproduction</a></nav>''']
parts.append('<section id="synthese"><h2>Ce que la vérification établit</h2><div class="cards">')
for title,native,gap in summary:parts.append('<article><h3>'+e(title)+'</h3><h4>Référence utilisable</h4><p>'+e(native)+'</p><h4>Couverture à compléter</h4><p>'+e(gap)+'</p></article>')
parts.append('</div><p class="status"><strong>'+str(d['estimation_consequences']['active_total_jh'])+' JH adoptés</strong> · Couverture sectorielle à requalifier · <strong>supplément net inconnu</strong>. Aucun nouveau total n’est adopté dans cet audit.</p><p>Les besoins détaillés sont dans le RFI, pages 13–14 (saisons), 18 (capacités fournisseurs) et 33–34 (allocations). Le pilotage industriel hebdomadaire est un besoin opportuniste/hors ERP dans le RFI. Un APS complet n’est pas ajouté au Core par défaut.</p></section>')
parts.append('<section id="complements"><h2>Sept compléments ou adaptations à instruire</h2><p>Les mécanismes communs restent financés une seule fois. Les postes ci-dessous distinguent ce qui existe déjà dans l’estimation de ce qui reste à dimensionner.</p>')
for i,c in enumerate(d['complements'],1):
 parts.append('<article class="detail" id="complement-'+e(c['id'])+'"><span class="tag">'+str(i)+' · '+e(c['topic'].capitalize())+'</span><h3>'+e(c['title'])+'</h3>'+ul(c['needed'])+'<h4>Financement existant et limite</h4><p>'+e(c['funding_assessment'])+'</p><h4>Propriétaire proposé, à instruire</h4><p>'+e(c['proposed_owner'])+'</p><h4>Travaux spécifiques au Groupe</h4><p>'+e(c['integration_boundary'])+'</p><p><strong>Supplément net : à dimensionner.</strong></p></article>')
parts.append('</section><section id="estimation"><h2>Conséquences sur l’estimation du Core System</h2><p>Le total reste la décision actuelle. Sa couverture des trois sujets ne peut pas être confirmée par les seuls composants Axelor étudiés. Le supplément doit être calculé après réutilisation des registres, politiques, cycles de commande, scénarios, ateliers et contrats de solveur déjà financés.</p><p>Dans les 630 JH du lot Décisions, l’allocation interne actuelle attribue 231 JH à Stock Optimization, 96 JH à Order Promising et 70 JH à Service Planning. Ces parts ne sont pas des estimations indépendantes ni des budgets à ajouter.</p><div class="note"><strong>Sensibilité, pas nouveau chiffrage.</strong> Le tableau mesure l’effet mathématique de 1 000 unités logiques équivalentes supplémentaires, avec les paramètres et formules courants. La taille des compléments manquants reste inconnue.</div><div class="scroll"><table><thead><tr><th>Unité</th><th>JH supplémentaires pour +1 000 unités équivalentes</th></tr></thead><tbody>')
labels={'supply-controls-java-spring':'Contrôles','orders-java-spring':'Commandes','master-plan-java-spring':'Master Plan','supply-decisions-java-spring':'Décisions d’approvisionnement'}
for s in d['estimation_consequences']['sensitivity']:parts.append('<tr><td>'+labels[s['unit_id']]+'</td><td>Environ +'+str(round(s['delta_jh']))+' JH</td></tr>')
parts.append('</tbody></table></div><p>Ces sensibilités ne s’additionnent pas pour constituer un budget des compléments. Les tailles doivent être consolidées au niveau de chaque unité cohérente avant d’appliquer COCOMO II.</p><h3>Conditions de réestimation</h3>'+ul(d['estimation_consequences']['reestimate_conditions'])+'</section>')
parts.append('<section id="preuves"><h2>Preuves techniques et reproduction</h2><p>'+e(d['method'])+'</p>')
for t in d['topics']:parts.append('<article class="detail"><h3>'+e(t['title'])+'</h3><h4>Observations</h4>'+ul(t['observed'])+'<h4>Limites et écarts</h4>'+ul(t['gaps'])+'</article>')
parts.append('<h3>Repères dans le code figé</h3><ul class="sources">')
for x in d['code_locations']:parts.append('<li><a href="'+e(x['url'])+'">'+e(x['method'])+'</a> · <code>'+e(x['path'].split('/')[-1])+':'+str(x['lines'][0])+'</code></li>')
parts.append('</ul><h3>Documentation officielle</h3><ul class="sources">')
for x in d['official_documents']:parts.append('<li><a href="'+e(x['url'])+'">'+e(x['id'])+' · documentation 9.0</a></li>')
parts.append('</ul><p>La documentation 9.0 complète la lecture. Le code v9.1.10 figé et ses empreintes définissent les composants réellement examinés.</p><h3>Reproduire les contrôles</h3><p>Depuis la racine du dépôt, avec les dépendances Python du modèle :</p><pre><code>python audits/2026-10-31-axelor-sectoriel/verify.py</code></pre><p>Le script vérifie les dix-sept fichiers archivés, leurs empreintes et références, les frontières de financement et les sensibilités via le moteur canonique. Il n’exécute pas Axelor et ne certifie pas la pertinence des hypothèses.</p><p><a href="../../sources/qualification-axelor-secteur-2026-10-31.json">Données de qualification et liens de preuve</a> · <a href="verification.json">Résultat des contrôles</a> · <a href="../../sources/client/rfi-besoins.pdf#page=13">RFI d’origine</a></p></section><p class="foot">Document généré depuis la qualification structurée. Il ne constitue pas une source de budget éditable.</p></main></html>')
(folder/'rapport.html').write_text(''.join(parts),encoding='utf-8')
print(folder/'rapport.html')
